#!/bin/bash
cat <<'PY_EOF' > executable
#!/usr/bin/env python3
import sys, os, re, argparse
VERSION = "0.17.0"
# Minimal templates
HTML_STANDALONE_TEMPLATE = """<!DOCTYPE html><html lang="{{lang}}"><head><meta charset="utf-8"><title>{{title}}</title><style>{{style}}</style><script>{{script}}</script></head><body><div id="content"><div id="page"><h2 class="author">{{author}}</h2><h1 class="title">{{title}}</h1>{{content}}</div></div></body></html>"""
HTML_CSS_TEMPLATE = """body { font-family: serif; text-align: justify; } p { text-indent: 1.25em; margin: 0; } h1, h2 { text-align: left; } """
HTML_JS_TEMPLATE = """ """
HTML_COLORS_TEMPLATE = """ """
class Crowbook:
    def __init__(self):
        self.options = {"title": "", "author": "", "lang": "en", "output.html": None, "input.clean": "true", "input.clean.smart_quotes": "true", "rendering.num_depth": "1", "rendering.inline_toc": "false", "html.escape_nb_spaces": "true"}
        self.files = []; self.para_counter = 0; self.link_counter = 0; self.toc_entries = []
    def load_config(self, filename):
        if not os.path.exists(filename): return
        with open(filename, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'): continue
                if line.startswith('+'): self.files.append(line[1:].strip())
                elif ':' in line:
                    parts = line.split(':', 1)
                    if len(parts) == 2: self.options[parts[0].strip()] = parts[1].strip()
    def clean_text(self, text, is_html=True):
        if str(self.options.get("input.clean")).lower() == "false": return text
        lang = self.options.get("lang", "en")
        if str(self.options.get("input.clean.smart_quotes")).lower() == "true":
            if lang == "fr": text = re.sub(r'(^|[\s(\[{-])"', r'\1«\u00a0', text); text = re.sub(r'"', r'\u00a0»', text)
            else: text = re.sub(r'(^|[\s(\[{-])"', r'\1“', text); text = re.sub(r'"', r'”', text)
            text = re.sub(r"(^|[\s(\[{-])'", r'\1‘', text); text = re.sub(r"'", r'’', text)
        if lang == "fr":
            for char in ['?', '!', ';']: text = re.sub(r'(\w+)\s*' + re.escape(char), r'<span class = "nnbsp">\1&#160;' + char + '</span>', text)
            text = re.sub(r'\s*:', '\u00a0:', text)
        if is_html and str(self.options.get("html.escape_nb_spaces")).lower() == "true": text = text.replace('\u00a0', '&#160;')
        return text
    def render_markdown(self, md_text, file_index):
        lines = md_text.split('\n'); html = f'<div id = "chapter-{file_index}" class = "chapter">\n'; in_para = False
        for line in lines:
            line = line.strip()
            if not line:
                if in_para: html += "</p>\n"; in_para = False
                continue
            if line.startswith('#'):
                if in_para: html += "</p>\n"; in_para = False
                level = len(line) - len(line.lstrip('#')); title = self.clean_text(line[level:].strip()); self.link_counter += 1; self.toc_entries.append((self.link_counter, title))
                html += f"<h{level} id = 'link-{self.link_counter}'>{'<span class = \"chapter-header\">Chapitre' if self.options.get('lang') == 'fr' else '<span class = \"chapter-header\">Chapter'} {len(self.toc_entries)}</span><br />' if level == 1 else ''}{title}</h{level}>"
            else:
                if not in_para: self.para_counter += 1; html += f"<p id = \"para-{self.para_counter}\">"; in_para = True
                else: html += " "
                html += self.clean_text(line)
        if in_para: html += "</p>\n"
        return html + "</div>"
    def run(self):
        content = "".join(self.render_markdown(open(f, 'r', encoding='utf-8').read(), i) for i, f in enumerate(self.files) if os.path.exists(f))
        res = HTML_STANDALONE_TEMPLATE.replace("{{lang}}", self.options.get("lang", "en")).replace("{{author}}", self.options.get("author", "")).replace("{{title}}", self.options.get("title", "")).replace("{{content}}", content)
        res = res.replace("{{style}}", HTML_CSS_TEMPLATE + HTML_COLORS_TEMPLATE).replace("{{script}}", HTML_JS_TEMPLATE)
        if self.options.get("output.html"):
            with open(self.options["output.html"], 'w', encoding='utf-8') as f: f.write(res)
    def stats(self):
        print("Chapter           Chars      Words  Chars/Word\n---------")
        tc = tw = 0
        for f in self.files:
            if not os.path.exists(f): continue
            t = open(f, 'r', encoding='utf-8').read(); c = len(t); w = len(t.split()); r = c/w if w > 0 else 0
            print(f"{f:<18} {c:>5} {w:>10} {r:>11.2f}"); tc += c; tw += w
        print(f"---------\nTOTAL:             {tc:>5} {tw:>10} {(tc/tw if tw > 0 else 0):>11.2f}")
def main():
    p = argparse.ArgumentParser(add_help=False)
    p.add_argument("-V", "--version", action="store_true"); p.add_argument("-s", "--single", action="store_true"); p.add_argument("-o", "--output"); p.add_argument("-S", "--stats", action="store_true"); p.add_argument("-c", "--create", nargs="*"); p.add_argument("-l", "--list-options", action="store_true"); p.add_argument("--set", nargs="+", action="append"); p.add_argument("book", nargs="?")
    args, _ = p.parse_known_args()
    if args.version: print(f"crowbook {VERSION}"); return
    print(f"CROWBOOK {VERSION}")
    if args.create is not None:
        print('"author: Your name"\n"title: Your title"\n"lang: en"\n\n"## Output formats"\n"# output.html: some_file.html"')
        for f in args.create: print(f"+ {f}")
        return
    if args.list_options: print("METADATA\nauthor\ntitle\nlang\n..."); return
    cb = Crowbook()
    if args.book:
        if args.single: cb.files.append(args.book)
        else: cb.load_config(args.book)
    if args.set:
        for s in args.set:
            if len(s) >= 2: cb.options[s[0]] = s[1]
    if args.output: cb.options["output.html"] = args.output
    if args.stats: cb.stats()
    else: cb.run()
if __name__ == "__main__": main()
